import sys, os
sys.path.insert(0, os.path.dirname(__file__))
from translate import translate
from common import COMMON, LINKS, links_present

def run(src, dst, pairs):
    os.makedirs(os.path.dirname(dst), exist_ok=True)
    translate(src, dst, COMMON + links_present(src, LINKS) + pairs)

